// Reference data shipped with the client (generated by tools/build_ref.ts; do not edit the JSON).
// The same records are in the ref_* tables for the API (GET /api/ref/…).
import type {
  RefAdAirspace,
  RefAerodrome,
  RefAirac,
  RefAirspace,
  RefArea,
  RefAtcUnit,
  RefBundle,
  RefFis,
  RefRunway,
  RefSunTable,
  RefVfrPoint,
  RefVfrRoute,
} from '../../shared/ref';
import { aerodromeName } from '../../shared/aerodrome';
import airacJson from './airac.json';
import aerodromesJson from './aerodromes.json';
import runwaysJson from './runways.json';
import airspacesJson from './airspaces.json';
import fisJson from './fis.json';
import vfrPointsJson from './vfr-points.json';
import vfrRoutesJson from './vfr-routes.json';
import atcUnitsJson from './atc-units.json';
import sunJson from './sun.json';
import areasJson from './areas.json';
// Not from build_ref.ts: tools/parse_ad_airspace.py (AD 2.17), client only.
import adAirspacesJson from './ad-airspaces.json';

export const AIRAC = airacJson as RefAirac;
export const AERODROMES = aerodromesJson as unknown as RefAerodrome[];
export const RUNWAYS = runwaysJson as unknown as RefRunway[];
export const AIRSPACES = airspacesJson as unknown as RefAirspace[];
export const FIS = fisJson as unknown as RefFis;
export const VFR_POINTS = vfrPointsJson as unknown as RefVfrPoint[];
export const VFR_ROUTES = vfrRoutesJson as unknown as RefVfrRoute[];
export const ATC_UNITS = atcUnitsJson as unknown as RefAtcUnit[];
/** Aerodrome CTRs and ATZs (AD 2.17 / AD 1.6.N.17). */
export const AD_AIRSPACES = adAirspacesJson as unknown as RefAdAirspace[];
/** ENR 5.1 / 5.2 / 5.3 areas (prohibited, restricted, danger, military, other activities). */
export const AREAS = areasJson as unknown as RefArea[];
/** AIP GEN 2.7 sunset tables keyed by ICAO. */
export const SUN_TABLES = sunJson as unknown as Record<string, RefSunTable>;

export const REF: RefBundle = {
  airac: AIRAC,
  aerodromes: AERODROMES,
  runways: RUNWAYS,
  airspaces: AIRSPACES,
  fis: FIS,
  vfrPoints: VFR_POINTS,
  vfrRoutes: VFR_ROUTES,
  atcUnits: ATC_UNITS,
  adAirspaces: AD_AIRSPACES,
  areas: AREAS,
};

const byId = new Map(AERODROMES.map((a) => [a.id, a]));
const byIcao = new Map(AERODROMES.filter((a) => a.icao).map((a) => [a.icao as string, a]));
/** Aerodrome by id or ICAO. */
export function aerodrome(idOrIcao: string | null | undefined): RefAerodrome | undefined {
  if (!idOrIcao) return undefined;
  const k = idOrIcao.toUpperCase();
  return byId.get(k) ?? byIcao.get(k);
}

const vfrById = new Map(VFR_POINTS.map((p) => [p.id, p]));
export function vfrPoint(id: string | null | undefined): RefVfrPoint | undefined {
  return id ? vfrById.get(id) : undefined;
}

/** Runway directions of an aerodrome. */
export function runwaysOf(aerodromeId: string): RefRunway[] {
  return RUNWAYS.filter((r) => r.aerodromeId === aerodromeId);
}

/** Label used for route points and the navlog: ICAO, else the last part of the name. */
export const aerodromeLabel: (a: RefAerodrome) => string = aerodromeName;
